<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">随机数</text><text class="nav-icon" @click="generate">🎲</text></view></view><view class="content"><view class="rn-display"><text class="rn-value">{{ result }}</text></view><view class="rn-form"><view class="form-row"><text class="form-l">最小值</text><input class="form-input" v-model="minVal" type="number" /></view><view class="form-row"><text class="form-l">最大值</text><input class="form-input" v-model="maxVal" type="number" /></view><view class="form-row"><text class="form-l">数量</text><input class="form-input" v-model="count" type="number" /></view></view><view class="rn-btn" @click="generate"><text>生成</text></view><view class="rn-history" v-if="history.length"><text class="hist-title">历史</text><text class="hist-item" v-for="(h, idx) in history" :key="idx">{{ h }}</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const minVal = ref(1); const maxVal = ref(100); const count = ref(1); const result = ref("?"); const history = ref([])
function generate() {
  var min = parseInt(minVal.value) || 0; var max = parseInt(maxVal.value) || 100; var c = parseInt(count.value) || 1
  var nums = []; for (var i = 0; i < c; i++) { nums.push(Math.floor(Math.random() * (max - min + 1)) + min) }
  result.value = nums.join(", ")
  history.value.unshift(result.value); if (history.value.length > 10) history.value.pop()
}
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#e17055,#d63031);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.rn-display{background:#fff;border-radius:24rpx;padding:48rpx;text-align:center;margin-bottom:24rpx}.rn-value{font-size:64rpx;font-weight:700;color:#e17055;font-family:monospace}.rn-form{background:#fff;border-radius:20rpx;padding:8rpx 24rpx;margin-bottom:24rpx}.form-row{display:flex;align-items:center;padding:20rpx 0;border-bottom:2rpx solid #f8f8f8}.form-row:last-child{border-bottom:none}.form-l{font-size:26rpx;color:#333;width:120rpx;flex-shrink:0}.form-input{flex:1;font-size:28rpx;height:56rpx;text-align:right}.rn-btn{background:linear-gradient(135deg,#e17055,#d63031);border-radius:16rpx;padding:24rpx;text-align:center;margin-bottom:24rpx}.rn-btn text{font-size:30rpx;color:#fff;font-weight:600}.rn-history{background:#fff;border-radius:20rpx;padding:16rpx 24rpx}.hist-title{font-size:24rpx;color:#999;display:block;margin-bottom:8rpx}.hist-item{font-size:24rpx;color:#666;display:block;padding:8rpx 0;border-bottom:2rpx solid #f8f8f8}</style>